/** [offset, colour, opacity?] */
type Stop = readonly [number, string, number?];
/** ['l', [x1, y1, x2, y2], stops] | ['r', [cx, cy, r], stops], all in user space */
type Gradient = readonly ['l' | 'r', readonly number[], readonly Stop[]];
/** [path data, fill colour | index into g, fill opacity?] */
type Shape = readonly [string, string | number, number?];
interface Art {
  readonly w: number;
  readonly h: number;
  readonly g: readonly Gradient[];
  readonly p: readonly Shape[];
}

